    Differential Revision: https://phabricator.services.mozilla.com/D282707

diff --git a/mailnews/protocols/ews/src/EwsFolder.cpp b/mailnews/protocols/ews/src/EwsFolder.cpp
index 8dcbb99de1c..a95f605ca82 100644
--- a/mailnews/protocols/ews/src/EwsFolder.cpp
+++ b/mailnews/protocols/ews/src/EwsFolder.cpp
@@ -1009,23 +1009,41 @@ NS_IMETHODIMP EwsFolder::DeleteMessages(

     // Define the listener with a success lambda callback, and start the
     // remote operation.
-    RefPtr<EwsSimpleMessageListener> listener = new EwsSimpleMessageListener(
-        headers, [self, copyListener, feedback](
-                     const nsTArray<RefPtr<nsIMsgDBHdr>>& srcHdrs,
-                     const nsTArray<nsCString>& ids, bool useLegacyFallback) {
-          nsresult rv = NS_OK;
-          auto listenerExitGuard = GuardCopyServiceListener(copyListener, rv);
-
-          rv = LocalDeleteMessages(self, srcHdrs);
-          NS_ENSURE_SUCCESS(rv, rv);
+    RefPtr<EwsSimpleMessageListener> listener =
+        new EwsSimpleFallibleMessageListener(
+            headers,
+            [self, copyListener, feedback](
+                const nsTArray<RefPtr<nsIMsgDBHdr>>& srcHdrs,
+                const nsTArray<nsCString>& ids, bool useLegacyFallback) {
+              nsresult rv = NS_OK;
+              auto listenerExitGuard =
+                  GuardCopyServiceListener(copyListener, rv);

-          if (feedback) {
-            // Reset the status bar.
-            return feedback->StopMeteors();
-          }
+              rv = LocalDeleteMessages(self, srcHdrs);

-          return NS_OK;
-        });
+              if (NS_SUCCEEDED(rv)) {
+                self->NotifyFolderEvent(kDeleteOrMoveMsgCompleted);
+              } else {
+                self->NotifyFolderEvent(kDeleteOrMoveMsgFailed);
+              }
+
+              if (feedback) {
+                // Reset the status bar.
+                return feedback->StopMeteors();
+              }
+
+              return NS_OK;
+            },
+
+            [self, feedback](nsresult rv) {
+              self->NotifyFolderEvent(kDeleteOrMoveMsgFailed);
+
+              if (feedback) {
+                return feedback->StopMeteors();
+              }
+
+              return NS_OK;
+            });

     nsCOMPtr<IEwsClient> client;
     rv = self->GetProtocolClient(getter_AddRefs(client));
diff --git a/mailnews/protocols/ews/test/unit/test_item_operations.js b/mailnews/protocols/ews/test/unit/test_item_operations.js
index 4d2784587ca..00fe7757923 100644
--- a/mailnews/protocols/ews/test/unit/test_item_operations.js
+++ b/mailnews/protocols/ews/test/unit/test_item_operations.js
@@ -769,3 +769,46 @@ add_task(async function test_change_flag_status() {
     "Waiting for message to be unflagged."
   );
 });
+
+add_task(async function test_hard_delete_item() {
+  const rootFolder = incomingServer.rootFolder;
+  await syncFolder(incomingServer, rootFolder);
+
+  const inboxFolder = rootFolder.getChildNamed("Inbox");
+  Assert.ok(!!inboxFolder, "Inbox folder should exist.");
+
+  const message = generator.makeMessages({ count: 1 })[0];
+  ewsServer.addNewItemOrMoveItemToFolder("message_to_delete", "inbox", message);
+
+  await syncFolder(incomingServer, inboxFolder);
+
+  const messageHeaders = [...inboxFolder.messages].filter(
+    header => header.getStringProperty("ewsId") == "message_to_delete"
+  );
+
+  Assert.equal(
+    messageHeaders.length,
+    1,
+    "Should be one message to delete in the inbox."
+  );
+
+  const eventPromise = PromiseTestUtils.promiseFolderEvent(
+    inboxFolder,
+    "DeleteOrMoveMsgCompleted"
+  );
+  inboxFolder.deleteMessages(
+    [messageHeaders[0]],
+    null,
+    true,
+    false,
+    null,
+    false
+  );
+  await eventPromise;
+
+  // Message should no longer be in the inbox.
+  const matchingMessages = [...inboxFolder.messages].filter(
+    header => header.getStringProperty("ewsId") == "message_to_delete"
+  );
+  Assert.equal(matchingMessages.length, 0, "Message should have been deleted.");
+});
